begin;
select plan(242);
select has_table('public', 'profiles', 'profiles table exists');
select has_table('public', 'content_items', 'content_items table exists');
select has_table('public', 'media_assets', 'media_assets table exists');
select col_is_pk('public', 'content_items', 'id', 'content_items.id is the primary key');
select policies_are('public', 'content_items', array['Published content is readable','Admins read all content','Admins create content','Admins update content','Admins delete content']);
select policies_are('public', 'profiles', array['Users read their profile']);
select policies_are('public', 'media_assets', array['Published media metadata is readable','Admins manage media metadata']);
select has_function('public', 'handle_new_admin_user', 'admin profile bootstrap function exists');
select has_trigger('auth', 'users', 'on_admin_user_created', 'new auth users receive an admin profile');
select has_table('public', 'content_revisions', 'content revision history exists');
select has_table('public', 'editorial_events', 'editorial event log exists');
select policies_are('public', 'content_revisions', array['Admins read content revisions']);
select policies_are('public', 'editorial_events', array['Admins read editorial events']);
select has_trigger('public', 'content_items', 'capture_content_revision_before_update', 'updates capture the previous content version');
select has_trigger('public', 'content_items', 'log_editorial_event_after_change', 'content changes are logged');
select ok((select count(*) from public.content_items where content_type = 'plant' and status = 'published' and coalesce(body->>'image_alt', '') <> '') >= 3, 'published starter plants have accessible image text');
select ok((select count(*) from public.content_items where content_type = 'plant' and status = 'published' and jsonb_array_length(coalesce(body->'care', '[]'::jsonb)) >= 2) >= 3, 'published starter plants have structured care steps');
select has_column('public', 'media_assets', 'license', 'media assets record a usage license');
select has_column('public', 'media_assets', 'mime_type', 'media assets record MIME type');
select has_column('public', 'media_assets', 'file_size', 'media assets record file size');
select has_column('public', 'media_assets', 'updated_at', 'media assets record metadata updates');
select has_index('public', 'media_assets', 'media_assets_created_index', 'media library has a chronological index');
select has_function('public', 'media_asset_usage', array['uuid'], 'media usage inspection function exists');
select has_trigger('public', 'media_assets', 'prevent_used_media_asset_deletion', 'used media cannot be deleted');
select is((select file_size_limit from storage.buckets where id = 'published_images'), 1572864::bigint, 'published image storage enforces the 1.5 MB delivery limit');
select is((select allowed_mime_types from storage.buckets where id = 'draft_images'), array['image/webp']::text[], 'draft image storage accepts only optimized WebP files');
select throws_ok($$insert into public.media_assets (object_path, alt_text, mime_type, file_size, width, height) values ('tests/unoptimized.jpg', 'Unoptimized test image', 'image/jpeg', 2000000, 3000, 2000)$$, '23514', 'new row for relation "media_assets" violates check constraint "media_assets_web_delivery_check"', 'media metadata rejects files that bypass the web-delivery limits');
select ok(has_function_privilege('authenticated', 'public.media_asset_usage(uuid)', 'execute'), 'authenticated editors can inspect media usage');
select ok(not has_function_privilege('anon', 'public.media_asset_usage(uuid)', 'execute'), 'anonymous visitors cannot inspect media usage');
insert into public.media_assets (id, object_path, alt_text) values ('00000000-0000-0000-0000-000000000081', 'tests/used-media.webp', 'A test image used by editorial content');
insert into public.content_items (title, slug, content_type, body) values ('Media usage test', 'media-usage-test', 'guide', '{"image":"http://127.0.0.1/storage/tests/used-media.webp"}'::jsonb);
select is((select count(*) from public.media_asset_usage('00000000-0000-0000-0000-000000000081')), 1::bigint, 'media usage reports linked editorial content');
select throws_ok($$delete from public.media_assets where id = '00000000-0000-0000-0000-000000000081'$$, 'P0001', 'Media asset is still used by editorial content.', 'deletion is blocked while the media is used');
delete from public.content_items where slug = 'media-usage-test';
select has_table('public', 'problem_profiles', 'problem profiles table exists');
select has_table('public', 'problem_plant_links', 'problem to plant relation table exists');
select col_is_pk('public', 'problem_profiles', 'content_id', 'problem profile is one-to-one with content');
select policies_are('public', 'problem_profiles', array['Published problem profiles are readable','Admins manage problem profiles']);
select policies_are('public', 'problem_plant_links', array['Published problem links are readable','Admins manage problem links']);
select ok((select count(*) from public.problem_profiles p join public.content_items c on c.id = p.content_id where c.status = 'published' and cardinality(p.symptoms) >= 2) >= 1, 'a structured published diagnostic exists');
select has_table('public', 'guide_profiles', 'guide profiles table exists');
select has_table('public', 'guide_plant_links', 'guide to plant relation table exists');
select col_is_pk('public', 'guide_profiles', 'content_id', 'guide profile is one-to-one with content');
select policies_are('public', 'guide_profiles', array['Published guide profiles are readable','Admins manage guide profiles']);
select policies_are('public', 'guide_plant_links', array['Published guide links are readable','Admins manage guide links']);
select ok((select count(*) from public.guide_profiles g join public.content_items c on c.id = g.content_id where c.status = 'published' and jsonb_array_length(g.steps) >= 4) >= 1, 'a structured published guide exists');
select has_table('public', 'calendar_profiles', 'calendar profiles table exists');
select has_table('public', 'calendar_entries', 'calendar entries table exists');
select has_table('public', 'calendar_plant_links', 'calendar to plant relation table exists');
select col_is_pk('public', 'calendar_profiles', 'content_id', 'calendar profile is one-to-one with content');
select policies_are('public', 'calendar_profiles', array['Published calendar profiles are readable','Admins manage calendar profiles']);
select policies_are('public', 'calendar_entries', array['Published calendar entries are readable','Admins manage calendar entries']);
select policies_are('public', 'calendar_plant_links', array['Published calendar links are readable','Admins manage calendar links']);
select ok((select count(distinct e.month) from public.calendar_entries e join public.content_items c on c.id = e.calendar_content_id where c.status = 'published') = 12, 'a published calendar covers all twelve months');
select has_table('public', 'review_profiles', 'review profiles table exists');
select has_table('public', 'review_criteria', 'review criteria table exists');
select has_table('public', 'review_products', 'review products table exists');
select has_table('public', 'review_product_scores', 'review score matrix exists');
select col_is_pk('public', 'review_profiles', 'content_id', 'review profile is one-to-one with content');
select policies_are('public', 'review_profiles', array['Published review profiles are readable','Admins manage review profiles']);
select policies_are('public', 'review_criteria', array['Published review criteria are readable','Admins manage review criteria']);
select policies_are('public', 'review_products', array['Published review products are readable','Admins manage review products']);
select policies_are('public', 'review_product_scores', array['Published review scores are readable','Admins manage review scores']);
select ok((select count(*) from public.review_profiles r join public.content_items c on c.id = r.content_id where c.status = 'published' and char_length(r.methodology) >= 80 and char_length(r.disclosure_text) >= 20 and (select count(*) from public.review_products p where p.review_content_id = r.content_id) >= 2 and (select count(*) from public.review_criteria criterion where criterion.review_content_id = r.content_id) >= 3) >= 1, 'a transparent structured published comparison exists');
select has_table('public', 'institutional_page_profiles', 'institutional page profiles table exists');
select col_is_pk('public', 'institutional_page_profiles', 'content_id', 'institutional page profile is one-to-one with content');
select policies_are('public', 'institutional_page_profiles', array['Published institutional profiles are readable','Admins manage institutional profiles']);
select ok((select count(*) from public.institutional_page_profiles p join public.content_items c on c.id = p.content_id where c.content_type = 'page' and c.status = 'published' and jsonb_array_length(p.sections) >= 2) = 7, 'seven structured institutional pages are published locally');
select ok((select count(*) from public.institutional_page_profiles where requires_legal_review) >= 3, 'pre-launch pages visibly retain legal or operator review flags');
select has_table('public', 'editorial_contributors', 'editorial contributors table exists');
select has_table('public', 'content_workflows', 'content workflow table exists');
select col_is_pk('public', 'content_workflows', 'content_id', 'content workflow is one-to-one with content');
select policies_are('public', 'editorial_contributors', array['Public contributors are readable','Admins manage contributors']);
select policies_are('public', 'content_workflows', array['Admins manage content workflows']);
select has_function('public', 'restore_content_revision', array['bigint'], 'safe revision restoration function exists');
select has_function('public', 'publish_due_content', 'approved scheduled publication function exists');
select has_trigger('public', 'content_workflows', 'log_content_workflow_event_after_update', 'workflow changes are logged');
select ok((select count(*) from public.editorial_contributors where is_active) >= 2, 'author and review desk placeholders exist');
select ok((select count(*) from public.content_workflows) = (select count(*) from public.content_items), 'every content item has a workflow record');
select has_column('public', 'content_items', 'search_vector', 'content has a stored full-text search document');
select has_index('public', 'content_items', 'content_items_search_index', 'published content has a GIN search index');
select has_function('public', 'search_prefix_query', array['text'], 'prefix search query helper exists');
select has_function('public', 'search_published_content', array['text', 'text', 'integer'], 'ranked published search function exists');
select has_function('public', 'suggest_published_searches', array['text', 'integer'], 'published search suggestion function exists');
select ok(has_function_privilege('anon', 'public.search_prefix_query(text)', 'execute'), 'anonymous search can execute the prefix helper');
select ok((select count(*) from public.search_published_content('basil', null, 24) where content_type = 'plant') >= 1, 'full-text search finds the published basil profile');
select ok((select count(*) from public.search_published_content('container', 'problem', 24) where content_type <> 'problem') = 0, 'search content type filter cannot leak other content types');
select has_table('public', 'plant_finder_profiles', 'plant finder profiles table exists');
select col_is_pk('public', 'plant_finder_profiles', 'content_id', 'plant finder profile is one-to-one with plant content');
select policies_are('public', 'plant_finder_profiles', array['Published plant finder profiles are readable','Admins manage plant finder profiles']);
select has_index('public', 'plant_finder_profiles', 'plant_finder_profiles_spaces_index', 'plant finder space filters use a GIN index');
select has_index('public', 'plant_finder_profiles', 'plant_finder_profiles_climates_index', 'plant finder climate filters use a GIN index');
select has_function('public', 'find_suitable_plants', array['integer', 'text', 'text', 'text', 'integer'], 'ranked plant finder function exists');
select ok(has_function_privilege('anon', 'public.find_suitable_plants(integer,text,text,text,integer)', 'execute'), 'anonymous visitors can execute the plant finder');
select ok((select count(*) from public.plant_finder_profiles) >= 3, 'starter plants have matching profiles');
select ok((select count(*) from public.content_items where content_type = 'tool' and slug = 'plant-finder' and status = 'published') = 1, 'plant finder has a published editorial record');
select is((select count(*) from public.find_suitable_plants(4, 'windowsill', 'low', 'general', 6)), 6::bigint, 'plant finder returns the requested six-item shortlist from the launch collection');
select is((select slug from public.find_suitable_plants(4, 'windowsill', 'low', 'general', 6) limit 1), 'container-chives', 'plant finder ranks low-care container chives first for a four-hour windowsill');
insert into public.content_items (id, content_type, status, title, slug, body) values ('00000000-0000-0000-0000-000000000093', 'plant', 'draft', 'Hidden finder plant', 'hidden-finder-plant', '{}'::jsonb);
insert into public.plant_finder_profiles (content_id, min_sun_hours, space_types, care_level, climates, match_note) values ('00000000-0000-0000-0000-000000000093', 0, array['windowsill'], 'low', array['general'], 'This draft must remain private.');
select is((select count(*) from public.find_suitable_plants(8, 'windowsill', 'attentive', 'general', 24) where slug = 'hidden-finder-plant'), 0::bigint, 'plant finder never exposes unpublished plants');
select has_function('public', 'calculate_container_size', array['text', 'integer', 'text'], 'container size calculation function exists');
select ok(has_function_privilege('anon', 'public.calculate_container_size(text,integer,text)', 'execute'), 'anonymous visitors can calculate a container size');
select is((select preferred_liters from public.calculate_container_size('fruiting-crop', 1, 'annual')), 20, 'one annual fruiting crop prefers a twenty-liter container');
select is((select minimum_depth_cm from public.calculate_container_size('fruiting-crop', 1, 'annual')), 35, 'fruiting crops receive a useful minimum root depth');
select ok((select preferred_liters from public.calculate_container_size('leafy-herb', 3, 'annual')) > (select preferred_liters from public.calculate_container_size('leafy-herb', 1, 'annual')), 'shared containers increase total recommended volume');
select has_function('public', 'calculate_watering_check', array['text', 'integer', 'text', 'text', 'text'], 'watering observation calculation function exists');
select ok(has_function_privilege('anon', 'public.calculate_watering_check(text,integer,text,text,text)', 'execute'), 'anonymous visitors can calculate a watering check routine');
select ok((select check_interval_hours from public.calculate_watering_check('moderate', 10, 'windy', 'hot', 'fast')) < (select check_interval_hours from public.calculate_watering_check('moderate', 10, 'sheltered', 'mild', 'balanced')), 'hot windy fast-draining conditions shorten the observation interval');
select ok((select warning like '%not a watering schedule%' from public.calculate_watering_check('moderate', 10, 'sheltered', 'mild', 'balanced')), 'watering result explicitly rejects automatic schedules');
select is((select count(*) from public.content_items where content_type = 'tool' and slug in ('pot-size-calculator', 'watering-calculator') and status = 'published'), 2::bigint, 'pot and watering tools have published editorial records');
select ok((select count(*) from public.search_published_content('pot size', 'tool', 24) where slug = 'pot-size-calculator') = 1, 'full-text search discovers the pot size calculator');
select has_function('public', 'get_monthly_growing_tasks', array['integer', 'text', 'text', 'text', 'integer'], 'monthly growing task function exists');
select ok(has_function_privilege('anon', 'public.get_monthly_growing_tasks(integer,text,text,text,integer)', 'execute'), 'anonymous visitors can request monthly growing tasks');
select is((select count(*) from public.get_monthly_growing_tasks(8, 'mediterranean', 'northern', 'container', 8)), 2::bigint, 'the August Mediterranean Northern Hemisphere container calendar returns its two published tasks');
select is((select context_score from public.get_monthly_growing_tasks(8, 'mediterranean', 'northern', 'container', 8) limit 1), 100, 'an exact climate, hemisphere, and space calendar receives the strongest context score');
select has_function('public', 'assess_frost_risk', array['numeric', 'text', 'text', 'boolean'], 'frost risk assessment function exists');
select ok(has_function_privilege('anon', 'public.assess_frost_risk(numeric,text,text,boolean)', 'execute'), 'anonymous visitors can assess frost risk');
select is((select risk_level from public.assess_frost_risk(2, 'tender', 'windy', true)), 'critical', 'a tender container in a windy two-degree forecast receives a critical decision level');
select is((select risk_level from public.assess_frost_risk(2, 'hardy', 'sheltered', false)), 'low', 'a hardy sheltered in-ground plant remains low risk at two degrees');
select ok((select risk_score from public.assess_frost_risk(2, 'tender', 'windy', true)) > (select risk_score from public.assess_frost_risk(2, 'tender', 'sheltered', false)), 'wind and container roots increase the cautious frost score');
select ok((select array_to_string(actions, ' ') like '%Do not use heaters, flames, or sealed plastic%' from public.assess_frost_risk(2, 'tender', 'windy', true)), 'frost actions explicitly reject unsafe heat and sealed covers');
select is((select count(*) from public.content_items where content_type = 'tool' and slug in ('planting-calendar', 'frost-risk') and status = 'published'), 2::bigint, 'calendar and frost tools have published editorial records');
select ok((select count(*) from public.search_published_content('frost risk', 'tool', 24) where slug = 'frost-risk') = 1, 'full-text search discovers the frost risk tool');
select has_function('public', 'plan_small_growing_space', array['numeric', 'numeric', 'text', 'integer', 'text'], 'small-space planning function exists');
select ok(has_function_privilege('anon', 'public.plan_small_growing_space(numeric,numeric,text,integer,text)', 'execute'), 'anonymous visitors can plan a small growing space');
select is((select total_area_m2 from public.plan_small_growing_space(200, 120, 'edge-only', 6, 'balcony')), 2.40::numeric, 'planner calculates the measured footprint in square metres');
select ok((select growing_area_m2 from public.plan_small_growing_space(200, 120, 'central-path', 6, 'balcony')) < (select growing_area_m2 from public.plan_small_growing_space(200, 120, 'edge-only', 6, 'balcony')), 'a central path reserves more access area than edge-only reach');
select ok((select suggested_modules from public.plan_small_growing_space(200, 120, 'edge-only', 2, 'balcony')) < (select suggested_modules from public.plan_small_growing_space(200, 120, 'edge-only', 8, 'balcony')), 'low light reduces the planning-module estimate');
select ok((select safety_note like '%does not verify structural load%' from public.plan_small_growing_space(200, 120, 'edge-only', 6, 'balcony')), 'planner explicitly rejects structural-load verification');
select has_function('public', 'guide_plant_observation', array['text', 'text', 'text', 'text'], 'plant observation guide function exists');
select ok(has_function_privilege('anon', 'public.guide_plant_observation(text,text,text,text)', 'execute'), 'anonymous visitors can build an observation checklist');
select is((select attention_level from public.guide_plant_observation('yellowing', 'wet', 'older-leaves', 'watering')), 'watch', 'yellowing with persistently wet roots receives a watch level');
select is((select attention_level from public.guide_plant_observation('insects', 'moist', 'isolated', 'none')), 'prompt', 'visible insect evidence prompts timely inspection');
select ok((select array_to_string(avoid_actions, ' ') like '%Do not apply fertilizer%' from public.guide_plant_observation('yellowing', 'wet', 'older-leaves', 'watering')), 'observation guide rejects automatic fertilizer and treatment');
select has_function('public', 'find_guided_problem_matches', array['text', 'text', 'text', 'integer'], 'published diagnostic matching function exists');
select ok(has_function_privilege('anon', 'public.find_guided_problem_matches(text,text,text,integer)', 'execute'), 'anonymous visitors can retrieve matching published diagnostic guides');
select ok((select slug = 'yellow-leaves-container-plants' and match_score = 100 from public.find_guided_problem_matches('yellowing', 'wet', 'older-leaves', 4) limit 1), 'yellow wet older leaves strongly match the published yellow-leaf guide');
select is((select count(*) from public.find_guided_problem_matches('spots', 'moist', 'isolated', 4)), 3::bigint, 'the matcher returns the three published guides relevant to visible spots');
select is((select count(*) from public.content_items where content_type = 'tool' and slug in ('garden-planner', 'guided-diagnosis') and status = 'published'), 2::bigint, 'planner and observation tools have published editorial records');
select ok((select count(*) from public.search_published_content('small space garden planner', 'tool', 24) where slug = 'garden-planner') = 1, 'full-text search discovers the small-space planner');
select has_function('public', 'content_public_route', array['text', 'text'], 'public route helper exists');
select is(public.content_public_route('problem', 'yellow-leaves'), '/plant-care/problems/yellow-leaves', 'route helper maps a diagnostic to its stable public URL');
select ok(has_function_privilege('anon', 'public.content_public_route(text,text)', 'execute'), 'anonymous rendering can resolve public content routes');
select has_function('public', 'admin_content_seo_audit', 'global editorial SEO audit exists');
select ok(has_function_privilege('authenticated', 'public.admin_content_seo_audit()', 'execute'), 'authenticated editors can run the global SEO audit');
select ok(not has_function_privilege('anon', 'public.admin_content_seo_audit()', 'execute'), 'anonymous visitors cannot run the editorial SEO audit');
select is((select count(*) from public.admin_content_seo_audit()), (select count(*) from public.content_items where status = 'published'), 'SEO audit covers every published content item');
select ok(not exists(select 1 from public.admin_content_seo_audit() where seo_score < 0 or seo_score > 100), 'every global SEO score stays within its documented scale');
select ok((select count(*) from public.admin_content_seo_audit() where not public_author) >= 1, 'SEO audit flags contributors that are not yet approved for public display');
select has_function('public', 'admin_keyword_cannibalization', 'keyword competition audit exists');
select ok(not has_function_privilege('anon', 'public.admin_keyword_cannibalization()', 'execute'), 'anonymous visitors cannot inspect editorial keyword targets');
select has_function('public', 'admin_internal_link_audit', 'structured internal-link audit exists');
select is((select count(*) from public.admin_internal_link_audit() where link_status = 'broken-target'), 0::bigint, 'current structured links do not point from public pages to unpublished targets');
select has_function('public', 'admin_launch_content_coverage', 'launch content coverage audit exists');
select ok((select published_count = 7 and launch_target = 7 and remaining_count = 0 and coverage_status = 'ready' from public.admin_launch_content_coverage() where content_type = 'tool'), 'all seven launch tools are covered');
select ok((select remaining_count = 0 and coverage_status = 'ready' from public.admin_launch_content_coverage() where content_type = 'plant'), 'launch audit marks the fifteen-plant target ready');
select has_function('public', 'get_public_editorial_meta', array['text'], 'privacy-safe public editorial metadata function exists');
select ok(has_function_privilege('anon', 'public.get_public_editorial_meta(text)', 'execute'), 'public pages can request approved editorial attribution');
select ok((select author_name is null and reviewer_name is null from public.get_public_editorial_meta('cherry-tomato')), 'private contributor placeholders are never exposed on public pages');
select is((select count(*) from public.content_items where content_type = 'plant' and status = 'published'), 15::bigint, 'the launch collection contains fifteen published plant profiles');
select is((select count(*) from public.content_items where content_type = 'problem' and status = 'published'), 10::bigint, 'the launch collection contains ten published diagnostic guides');
select is((select jsonb_array_length(body -> 'sources') from public.content_items where slug = 'container-radish'), 3, 'container radish records three named editorial sources');
select is((select body ->> 'image' from public.content_items where slug = 'container-radish'), '/images/container-radish.jpg', 'container radish uses its optimised project image');
select ok((select count(*) from public.plant_finder_profiles profile join public.content_items content on content.id = profile.content_id where content.slug = 'container-radish' and profile.min_sun_hours = 4) = 1, 'container radish participates in the explainable plant finder');
select is((select count(*) from public.problem_profiles profile join public.content_items content on content.id = profile.content_id where content.slug in ('wilting-container-plants', 'aphids-edible-container-plants', 'powdery-mildew-balcony-plants')), 3::bigint, 'three launch diagnostics have complete structured profiles');
select ok(not exists(select 1 from public.content_items where slug in ('wilting-container-plants', 'aphids-edible-container-plants', 'powdery-mildew-balcony-plants') and jsonb_array_length(body -> 'sources') < 2), 'each new diagnostic records at least two visible sources');
select is((select count(*) from public.problem_plant_links links join public.content_items plant on plant.id = links.plant_content_id where plant.slug = 'container-radish'), 5::bigint, 'container radish is connected to five relevant launch diagnostics');
select is((select slug from public.find_guided_problem_matches('insects', 'moist', 'isolated', 4) limit 1), 'aphids-edible-container-plants', 'guided observation leads insect evidence to the published aphid guide');
select is((select slug from public.find_guided_problem_matches('spots', 'moist', 'isolated', 4) limit 1), 'powdery-mildew-balcony-plants', 'guided observation leads powdery spots to the mildew guide');
select is((select slug from public.find_guided_problem_matches('wilting', 'wet', 'whole-plant', 4) limit 1), 'wilting-container-plants', 'guided observation leads wet-root wilting to the cautious wilting guide');
select ok((select remaining_count = 0 from public.admin_launch_content_coverage() where content_type = 'plant') and (select remaining_count = 0 from public.admin_launch_content_coverage() where content_type = 'problem'), 'launch coverage confirms that plant and diagnostic targets are complete');
select ok(not exists(select 1 from public.content_workflows workflow join public.content_items content on content.id = workflow.content_id where content.slug in ('container-radish', 'wilting-container-plants', 'aphids-edible-container-plants', 'powdery-mildew-balcony-plants') and (workflow.review_state <> 'approved' or workflow.author_id is null or workflow.reviewer_id is null or workflow.author_id = workflow.reviewer_id)), 'launch batch has distinct assigned author and reviewer with approval recorded');
select is((select count(*) from public.content_items where slug in ('container-leaf-lettuce','baby-spinach-containers','dwarf-french-bean-container','dwarf-mangetout-pea-container','container-chives','flat-leaf-parsley-container','spearmint-container','container-thyme','container-rosemary','compact-sweet-pepper-container','patio-cucumber-container') and content_type = 'plant' and status = 'published'), 11::bigint, 'launch batch two publishes eleven additional plants');
select ok(not exists(select 1 from public.content_items where slug in ('container-leaf-lettuce','baby-spinach-containers','dwarf-french-bean-container','dwarf-mangetout-pea-container','container-chives','flat-leaf-parsley-container','spearmint-container','container-thyme','container-rosemary','compact-sweet-pepper-container','patio-cucumber-container') and jsonb_array_length(body -> 'sources') < 2), 'every batch-two plant records at least two visible sources');
select ok(not exists(select 1 from public.content_items where slug in ('container-leaf-lettuce','baby-spinach-containers','dwarf-french-bean-container','dwarf-mangetout-pea-container','container-chives','flat-leaf-parsley-container','spearmint-container','container-thyme','container-rosemary','compact-sweet-pepper-container','patio-cucumber-container') and jsonb_array_length(body -> 'care') < 3), 'every batch-two plant provides at least three structured care steps');
select ok(not exists(select 1 from public.content_items where slug in ('container-leaf-lettuce','baby-spinach-containers','dwarf-french-bean-container','dwarf-mangetout-pea-container','container-chives','flat-leaf-parsley-container','spearmint-container','container-thyme','container-rosemary','compact-sweet-pepper-container','patio-cucumber-container') and coalesce(body ->> 'image_alt', '') = ''), 'every batch-two plant has accessible image text');
